#!/usr/bin/env python3
import base64
import os
from pathlib import Path
import zlib

DEST_DIR = Path(
    os.environ.get(
        "RESTORE_DIR",
        r"./flow-typing-compiler"
    )
).resolve()

FILES = {'README.md': '', 'examples.fl': '', 'Cargo.toml': 'eNpVjsEOgjAQRO/7Fc2ehQAa4sUvIT1s2gUbYNu0RUOM/y5EPHh9M28yXSAz0sAahGZWN4X95J9FXoOToTB+Dm7iiPDgmJyXvVCVdVkhsHX5IE3VXBCgsxxYLItxnDRQdGSFv0q7K+a+zGlcN/JS/4PnLT6pnikvkdMGOwyRckat3jD5waej2JY1wiKcDAWOvztXhA/clTwW', 'flow/FlowPrelude.hs': '', 'flow/Main.hs': 'eNpNjs0KwjAQhO99ioEeTMDmAQQFDypC/QEtXrxEs8VA2mjaEkV8d1NtxcPC7nyzu/NMYqTT9SKbLmbIypO9k9o3V0MV4uQVRYVVjSGspC7hL+QoinRxta7G7C6Lj+/WSKNzTaonc2P91pFpFIEdrDMKTAjOe94xkeqSpIOskPZo96hqKsRy8weXmxCj/T8aIQ0IjH/nMbyuL19jK7d19EgmOMuKfgHFx9wF8Rw2B2N8iE4Y8HaDxaEbInPhOmIewr4Bc0pYOw==', 'flow/fourmolu.yaml': '', 'flow/flow.cabal': '', 'flow/.gitignore': 'eNrTT8ksLtHNSy0vLqnMSeXSd61IzC3ISS3WyyjmAgCV7QoX', 'flow/Examples.hs': '', 'src/parse.rs': '', 'src/layout.rs': '', 'src/infer.rs': '', 'src/rename.rs': '', 'src/main.rs': '', 'src/out_of_scope.rs': 'eNplj0EKwyAQRfeeYpKVQk/Q0F4lGDsSQR0ZtZuQu8ekpSD9zGLm8XkwQRummavHPADVMpOds6GEsAlokQoez+9+pkYXkseAseBrkD9+Ziyry7Dgqt+OKkM7mhHIwsdoieGqGArJeWSQyNwgBleaDnSBbb9fo8Zb57atP0jVQ+/iPzTka4gdVte2T2IXqS7SsC6ooGbsPp7EAWnSSzc=', 'src/core.rs': '', 'src/lex.rs': '', 'src/error.rs': ''}

def main():
    print(f"Creating files in: {DEST_DIR}")
    DEST_DIR.mkdir(parents=True, exist_ok=True)

    for rel_path, b64_data in FILES.items():
        target_path = DEST_DIR / rel_path
        target_path.parent.mkdir(parents=True, exist_ok=True)

        data = zlib.decompress(base64.b64decode(b64_data))
        with open(target_path, "wb") as f:
            f.write(data)
        print(f"  + {rel_path}")

    print(f"\nSuccessfully created {len(FILES)} files.")

if __name__ == "__main__":
    main()
